/**
 * Garage Daytona: new site footer (added by Claude).
 * Hides the old Elementor footer section (last top-level section with the site logo) and prints one shared footer.
 * The old section is only hidden with CSS, never deleted: removing this file brings it back.
 * Kill switch: wp option update gdf_off 1
 */
if (!defined('ABSPATH')) exit;

function gdf_old_id() {
	static $id = null;
	if ($id !== null) return $id;
	$id = '';
	if (is_admin() || !is_singular('page') || (int) get_option('gdf_off', 0) === 1) return $id;
	if (isset($_GET['elementor-preview']) || isset($_GET['oldfooter'])) return $id;
	$raw = get_post_meta(get_queried_object_id(), '_elementor_data', true);
	if (!$raw) return $id;
	$d = json_decode($raw, true);
	if (!is_array($d) || count($d) < 2) return $id;
	$last = end($d);
	$hasLogo = false;
	$walk = function ($x) use (&$walk, &$hasLogo) {
		foreach (($x['elements'] ?? array()) as $c) {
			if (($c['elType'] ?? '') === 'widget' && ($c['widgetType'] ?? '') === 'wpr-logo') $hasLogo = true;
			$walk($c);
		}
	};
	$walk($last);
	if ($hasLogo && !empty($last['id'])) $id = preg_replace('/[^a-z0-9]/i', '', $last['id']);
	return $id;
}

add_action('wp_head', function () {
	$id = gdf_old_id();
	if (!$id) return;
	if (!function_exists('gdh_old_id') || !gdh_old_id()) {
		echo '<link rel="preload" as="style" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@100..125,600..900&family=Hanken+Grotesk:wght@500;600;700&display=swap"><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@100..125,600..900&family=Hanken+Grotesk:wght@500;600;700&display=swap" media="print" onload="this.media=\'all\'"><noscript><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@100..125,600..900&family=Hanken+Grotesk:wght@500;600;700&display=swap"></noscript>';
	}
	echo '<style id="gdf-css">.elementor-element.elementor-element-' . $id . '{display:none!important}' . GDF_CSS . '</style>';
}, 21);

add_action('wp_footer', function () {
	if (!gdf_old_id()) return;
	$nav = ''; $svc = ''; $contact = home_url('/contact/');
	if (function_exists('gdh_menu')) {
		foreach (gdh_menu() as $it) {
			if ($it['kids']) { foreach ($it['kids'] as $k) $svc .= '<li><a href="' . esc_url($k['u']) . '">' . esc_html($k['t']) . '</a></li>'; }
			else {
				$nav .= '<li><a href="' . esc_url($it['u']) . '">' . esc_html($it['t']) . '</a></li>';
				if (stripos($it['t'], 'contact') !== false) $contact = $it['u'];
			}
		}
	}
	$home = esc_url(home_url('/'));
