<script>
(function(){
 var N=["Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi","Dimanche"];
 function run(){var n=new Date(new Date().toLocaleString("en-US",{timeZone:"Europe/Zurich"}));var d=n.getDay(),m=n.getHours()*60+n.getMinutes(),ti=(d+6)%7;var open=d>=1&&d<=5&&m>=450&&m<1020,t;
  if(open)t="Ouvert · jusqu'à 17:00";else if(d===0||d===6)t="Sur rendez-vous";else if(m<450)t="Fermé · ouvre à 07:30";else t=d===5?"Fermé · ouvre lundi":"Fermé · ouvre demain 07:30";
  document.querySelectorAll("#gd-ftr").forEach(function(f){var l=f.querySelector(".live");l.classList.toggle("closed",!open);l.querySelector(".st").textContent=t;
   f.querySelector(".days").innerHTML=N.map(function(x,i){return '<li'+(i===ti?' class="td"':'')+'><span>'+x+'</span><b>'+(i<5?"07:30 – 17:00":"Sur rendez-vous")+'</b></li>'}).join("");
   f.querySelector(".y").textContent=n.getFullYear()})}
 run();setInterval(run,60000);
 document.querySelectorAll("#gd-ftr .col h3 button").forEach(function(b){b.addEventListener("click",function(){b.closest(".col").classList.toggle("open")})});
})();
</script>
